import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import Loading from '../../loading/Loading';
import './CompanyZapatos.css';
import CompanyMenu from '../Company_Menu/CompanyMenu';


//!importamos el localstorang para permanencia de datos 

import { getColores, setColores, getEmpresa, setEmpresa, getTallas, setTallas, getMarcas, setMarcas } from "../Company_Localstorang/Company_Localstorang";

import {Historial_Local} from '../../../Redux/Actions/Empresa/Actions-Empresa'

import alertify from 'alertifyjs';
import 'alertifyjs/build/css/alertify.css';

const CompanyZapatos = () => {
    const [loading, setLoading] = useState(true);
    const dispatch = useDispatch()
    const colores = useSelector((state) => state.COLORES);
    const Empresa = useSelector((state) => state.EMPRESA);
    const talla = useSelector((state) => state.TALLAS);
    const marca = useSelector((state) => state.MARCAS);
    

    const [formData, setFormData] = useState({
        name:'',
        color: '',
        talla: '',
        costo: '',
        marca: '',
        modelo: '',
        descripcion: '',
        calidad: '',
        url: ''
    });

    useEffect(() => {
        const timer = setTimeout(() => {
            setLoading(false);
            getColores(colores)
            getEmpresa(Empresa)
            getTallas(talla)
            getMarcas(marca)
            dispatch(Historial_Local())


        }, 3000);

        return () => clearTimeout(timer);
    }, []);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData({ ...formData, [name]: value });
        alert(value)
    };

    const handleFileChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => {
                setFormData({ ...formData, url: reader.result });
            };
            reader.readAsDataURL(file);
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        console.log('Datos del zapato:', formData);
        // Aquí puedes enviar formData a tu backend o realizar otra acción
    };

    const hanldeAddMarca = ()=>{
        alertify.prompt(
            'Agregar Marca',
            'Ingrese el nombre de la nueva marca:',
            formData.name,
            function (evt, value) {
              if (value.trim() !== '') {
                setFormData({ ...formData, name: value });
                
                alertify.alert('Mensaje','Marca agregada con éxito');
              } else {
                alertify.alert('Mensaje','El nombre de la marca no puede estar vacío');
                
              }
            },
            function () {
              alertify.error('Operación cancelada');
            }
          ).set({ labels: { ok: 'Guardar', cancel: 'Cancelar' } });
    }

const hanldeAddTalla = ()=>{

}

    return (
        <div>
            {loading ? <Loading /> : null
            }
            <CompanyMenu className="nav-menu" />
            <div className="body-zapatos">
                <h2>Crear Nuevo Zapato</h2>
                <form className="form-zapatos" onSubmit={handleSubmit}>
                    <div className="form-group">
                        <label>Color:</label>
                        <select 
                            name="color" 
                            value={formData.color} 
                            onChange={handleChange}
                        >
                            <option value="">Seleccione un color</option>
                            {colores.map((color) => (
                                <option key={color.id} value={color.color}>
                                    {color.color}
                                </option>
                            ))}
                        </select>
                    </div>
                    <div className="form-group">
                        <label>Talla:</label>
                        <div className='grupor-flex'>
                        <select 
                            name="color" 
                            value={formData.color} 
                            onChange={handleChange}
                        >
                            <option value="">Seleccione un color</option>
                            {talla.map((talla) => (
                                <option key={talla.id} value={talla.talla}>
                                    {talla.talla}
                                </option>
                            ))}
                            
                        </select>
                        <label className='btn-mas' onClick={hanldeAddTalla} title='Agrega un una nueva marca'>+</label>
                        </div>
                    </div>
                    <div className="form-group">
                        <label>Costo:</label>
                        <input 
                            type="number" 
                            name="costo" 
                            value={formData.costo} 
                            onChange={handleChange} 
                        />
                    </div>
                    <div className="form-group">
                        <label>Marca:</label>
                        <div className='grupor-flex'>
                        <select 
                            name="marca" 
                            value={formData.marca} 
                            onChange={handleChange}
                        >
                            <option value="">Seleccione un marca</option>
                            {  marca.map((marcas) => (
                                <option key={marcas.id} value={marcas.marca}>
                                    {marcas.marca}
                                </option>
                            ))}
                        </select>
                        <label className='btn-mas' onClick={hanldeAddMarca} title='Agrega un una nueva marca'>+</label>
                        </div>
                    </div>
                    <div className="form-group">
                        <label>Modelo:</label>
                        <input 
                            type="text" 
                            name="modelo" 
                            value={formData.modelo} 
                            onChange={handleChange} 
                        />
                    </div>
                    <div className="form-group">
                        <label>Calidad:</label>
                        <select 
                            name="calidad" 
                            value={formData.calidad} 
                            onChange={handleChange} 
                        >
                            <option value="">Seleccione</option>
                            <option value="AA">AA</option>
                            <option value="AAA">AAA</option>
                            <option value="Tipo Original">Tipo Original</option>
                            <option value="Original">Original</option>
                        </select>
                    </div>
                    <div className="form-group form-group-textarea">
                        <label>Descripción:</label>
                        <textarea 
                            name="descripcion" 
                            value={formData.descripcion} 
                            onChange={handleChange} 
                        ></textarea>
                    </div>
                    <div className="form-group">
                        <label>Subir Imagen:</label>
                        <input 
                            type="file" 
                            accept="image/*" 
                            onChange={handleFileChange} 
                        />
                    </div>
                    {formData.url && (
                        <div className="form-group">
                            <label>Vista Previa:</label>
                            <img src={formData.url} alt="Vista previa" className="img-preview" />
                        </div>
                    )}
                    <button type="submit">Guardar Zapato</button>
                </form>
            </div>
        </div>
    );
};

export default CompanyZapatos;
